@MainActor final class NativeCaptureRetentionTests: XCTestCase {
    private func ready() -> (NativeCaptureHarness, CaptureProbe) {
        let m = NativeCaptureHarness(), probe = CaptureProbe()
        m.session.currentFrame = .init(capturedImage: .init(probe))
        m.photoViewID = UUID()
        return (m, probe)
    }
    func testRepeatedCaptureRetainsOnlyOneNativeFrameWithoutReplacingOwner() async throws {
        let (m, probe) = ready(); defer { probe.finish() }
        // All callers start from an idle slot; none gets a manual head start.
        await withTaskGroup(of: Void.self) { group in
            for _ in 0..<100 { group.addTask { await m.captureExploreSnapshot() } }
            await group.waitForAll()
        }
        let task = try XCTUnwrap(m.exploreTask), lease = try XCTUnwrap(m.selectedPhotoNativeLease)
        await fulfillment(of: [probe.entered], timeout: 2)
        XCTAssertEqual(probe.calls, 1); XCTAssertEqual(m.selectedPhotoNativeLease, lease)
        XCTAssertEqual(m.cancelledDescriptions, 1)
        XCTAssertEqual(m.clearedDocuments, 1)
        probe.finish(); await task.value
        XCTAssertNil(m.selectedPhotoNativeLease); XCTAssertNotNil(m.exploreSnapshot)
    }
    func testClearRetiresOutputButHoldsInFlightPixelsUntilNativeCompletion() async throws {
        let (m, probe) = ready(); defer { probe.finish() }
        weak var pixels = m.session.currentFrame?.capturedImage
        m.captureExploreSnapshot(); let task = try XCTUnwrap(m.exploreTask)
        let lease = try XCTUnwrap(m.selectedPhotoNativeLease)
        await fulfillment(of: [probe.entered], timeout: 2)
        m.session.currentFrame = nil; m.clearExploreSnapshot()
        XCTAssertNotNil(pixels); XCTAssertEqual(m.selectedPhotoNativeLease, lease)
        XCTAssertNil(m.beginSelectedPhoto(viewID: try XCTUnwrap(m.photoViewID)))
        for _ in 0..<100 { m.captureExploreSnapshot() }
        XCTAssertEqual(probe.calls, 1); XCTAssertNil(m.exploreSnapshot)
        probe.finish(); await task.value
        XCTAssertNil(m.exploreSnapshot); XCTAssertNil(m.selectedPhotoNativeLease)
        XCTAssertNil(pixels, "Unneeded capture is reclaimed only after the native reader returns")
        XCTAssertNotNil(m.beginSelectedPhoto(viewID: try XCTUnwrap(m.photoViewID)))
    }
    func testCancelledBeforeTaskStartsNeverInvokesVisionAndReleasesPixels() async throws {
        let (m, probe) = ready(); defer { probe.finish() }
        weak var pixels = m.session.currentFrame?.capturedImage
        m.captureExploreSnapshot(); let task = try XCTUnwrap(m.exploreTask)
        m.session.currentFrame = nil; m.clearExploreSnapshot()
        await task.value
        XCTAssertEqual(probe.calls, 0); XCTAssertNil(m.selectedPhotoNativeLease)
        XCTAssertNil(m.exploreSnapshot); XCTAssertNil(pixels)
    }
    func testLibraryTransferLeaseAlsoBlocksCameraAndSurvivesClear() throws {
        let (m, probe) = ready(); defer { probe.finish() }
        let selection = try XCTUnwrap(m.beginSelectedPhoto(viewID: try XCTUnwrap(m.photoViewID)))
        m.captureExploreSnapshot()
        XCTAssertEqual(m.selectedPhoto.selection, selection)
        XCTAssertEqual(m.selectedPhotoNativeLease, selection.id); XCTAssertNil(m.exploreTask)
        XCTAssertEqual(m.cancelledDescriptions, 0); XCTAssertEqual(probe.calls, 0)
        m.clearExploreSnapshot(); m.captureExploreSnapshot()
        XCTAssertEqual(m.selectedPhotoNativeLease, selection.id); XCTAssertNil(m.exploreTask)
        m.finishSelectedPhotoNativeWork(selection); XCTAssertNil(m.selectedPhotoNativeLease)
    }
    func testWrongLibraryCompletionCannotReleaseCameraLease() async throws {
        let (m, probe) = ready(); defer { probe.finish() }
        m.captureExploreSnapshot(); let task = try XCTUnwrap(m.exploreTask)
        let lease = try XCTUnwrap(m.selectedPhotoNativeLease)
        await fulfillment(of: [probe.entered], timeout: 2)
        var other = SelectedPhotoReference()
        let unrelated = try XCTUnwrap(other.select(viewID: UUID(), generation: 2, question: "Read this photo", now: 10))
        m.finishSelectedPhotoNativeWork(unrelated)
        XCTAssertEqual(m.selectedPhotoNativeLease, lease)
        probe.finish(); await task.value
        XCTAssertNil(m.selectedPhotoNativeLease)
    }
    func testBackgroundAndSessionReplacementDropLateResultButReleaseLease() async throws {
        for background in [true, false] {
            let (m, probe) = ready(); defer { probe.finish() }
            m.captureExploreSnapshot(); let task = try XCTUnwrap(m.exploreTask)
            await fulfillment(of: [probe.entered], timeout: 2)
            if background { m.assistantSession.foregroundActive = false }
            else { m.assistantSession.generation += 1 }
            probe.finish(); await task.value
            XCTAssertNil(m.exploreSnapshot); XCTAssertNil(m.selectedPhotoNativeLease)
        }
    }
    func testUnavailableCaptureAndFailedPreviewDoNotLeakLease() {
        let (m, probe) = ready(); defer { probe.finish() }
        m.running = false; m.captureExploreSnapshot()
        XCTAssertNil(m.selectedPhotoNativeLease); XCTAssertNil(m.exploreTask)
        m.running = true; m.session.currentFrame?.capturedImage.renderable = false
        m.captureExploreSnapshot()
        XCTAssertNil(m.selectedPhotoNativeLease); XCTAssertNil(m.exploreTask)
        XCTAssertEqual(probe.calls, 0)
    }
}
